import random

def get_girth(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for start_node in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start_node] = 0
        queue = [start_node]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    min_cycle = min(min_cycle, dist[u] + dist[v] + 1)
    return min_cycle

def is_5_colorable(n, edges):
    # Backtracking for 5-coloring
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    def can_color(u):
        if u == n:
            return True

        # Try colors 0-4
        for c in range(5):
            safe = True
            for v in adj[u]:
                if colors[v] == c:
                    safe = False
                    break
            if safe:
                colors[u] = c
                if can_color(u + 1):
                    return True
                colors[u] = -1
        return False

    return can_color(0)

def solve():
    n = 19
    num_edges = 27

    # Try to build the graph by adding edges one by one
    # and checking the girth constraint.

    for _ in range(1000):
        edges = []
        # Start with a cycle of 19 to ensure girth 19
        for i in range(n):
            edges.append((i, (i + 1) % n))

        # Add remaining edges
        while len(edges) < num_edges:
            u = random.randint(0, n-1)
            v = random.randint(0, n-1)
            if u == v: continue
            if u > v: u, v = v, u
            if (u, v) in edges: continue

            new_edges = edges + [(u, v)]
            if get_girth(n, new_edges) >= 8:
                edges = new_edges
            else:
                # If adding this edge violates girth, maybe try another one
                pass

        if len(edges) == num_edges:
            if is_5_colorable(n, edges):
                return edges
    return None

result = solve()
